// Builds src/content/docs/developers/api/*.md from data/api-catalogue.json
// (generated by Graft) and data/endpoint-docs.mjs (the prose).
// Fails when an endpoint is missing prose, or prose names an endpoint that no
// longer exists, so the reference cannot drift from the API.
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { DOCS, GROUPS } from "../data/endpoint-docs.mjs";

const OUT = "src/content/docs/developers/api";
const catalogue = JSON.parse(readFileSync("data/api-catalogue.json", "utf8"));

// Internal surfaces: the platform-admin console and Stripe's own callbacks.
const INTERNAL_GROUPS = new Set(["admin", "webhooks"]);
const endpoints = catalogue.endpoints.filter((e) => !INTERNAL_GROUPS.has(e.group));

const problems = [];
const ids = new Set(endpoints.map((e) => e.id));
for (const e of endpoints) {
  if (!DOCS[e.id]) problems.push(`no description for ${e.id}`);
  if (!GROUPS[e.group]) problems.push(`no group entry for "${e.group}" (${e.id})`);
}
for (const id of Object.keys(DOCS)) if (!ids.has(id)) problems.push(`description for unknown endpoint ${id}`);
if (problems.length) {
  console.error("API reference is out of sync:\n - " + problems.join("\n - "));
  process.exit(1);
}

const AUTH = {
  public: "None",
  session: "Bearer token",
};
const json = (v) => JSON.stringify(v, null, 2);

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

const order = Object.keys(GROUPS);
const byGroup = Object.groupBy(endpoints, (e) => e.group);

order.forEach((group, i) => {
  const list = byGroup[group];
  if (!list) return;
  const { title, blurb } = GROUPS[group];
  let md = `---\ntitle: "${title}"\ndescription: "${blurb}"\nsidebar:\n  order: ${i + 1}\n---\n\n${blurb}\n\n`;
  md += `:::note\nThis page is generated from Graft's API catalogue. Base URL is your Graft host; every path below starts with it.\n:::\n\n`;
  for (const e of list) {
    const doc = DOCS[e.id];
    md += `## \`${e.method}\` \`${e.path}\`\n\n`;
    md += `${doc.d}\n\n`;
    md += `**Auth:** ${AUTH[e.auth]}`;
    if (e.params.length) md += ` · **Path parameters:** ${e.params.map((p) => `\`${p}\``).join(", ")}`;
    md += `\n\n`;
    if (doc.body) md += `**Request body**\n\n\`\`\`json\n${json(doc.body)}\n\`\`\`\n\n`;
    if (doc.response) md += `**Response**\n\n\`\`\`json\n${json(doc.response)}\n\`\`\`\n\n`;
  }
  writeFileSync(`${OUT}/${group}.md`, md);
});

const count = endpoints.length;
writeFileSync(`${OUT}/index.md`,
  `---\ntitle: "Endpoint reference"\ndescription: "Every public Graft endpoint, grouped by area."\nsidebar:\n  order: 0\n---\n\n` +
  `${count} endpoints, generated from Graft's API catalogue. Read [Conventions](../conventions/) first for the response envelope, errors, pagination and rate limits.\n\n` +
  order.filter((g) => byGroup[g]).map((g) => `- [${GROUPS[g].title}](./${g}/) (${byGroup[g].length}): ${GROUPS[g].blurb}`).join("\n") + "\n");

console.log(`Generated ${count} endpoints across ${order.filter((g) => byGroup[g]).length} pages.`);
